import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Silent failures — when nothing prints","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/silent-failures.md","filePath":"troubleshooting/silent-failures.md"}'),n={name:"troubleshooting/silent-failures.md"};function r(i,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="silent-failures-—-when-nothing-prints" tabindex="-1">Silent failures — when nothing prints <a class="header-anchor" href="#silent-failures-—-when-nothing-prints" aria-label="Permalink to &quot;Silent failures — when nothing prints&quot;">​</a></h1><p>Most of Open Cube OS fails loudly: an error string, a <code>FAIL</code> verdict, a panic banner. This page is about the other class: things that go wrong <strong>without printing anything</strong>, why the design made them quiet, and the exact commands that surface them. Read this once; it will save you an afternoon.</p><p>The one-line rule: <strong><code>health</code> first, <code>dmesg 100</code> second, <code>crashlog</code> third.</strong> Those three see through almost every silent failure.</p><hr><h2 id="_1-output-capture-—-when-your-console-shows-nothing-because-the" tabindex="-1">1. Output capture — when your console shows nothing because the <a class="header-anchor" href="#_1-output-capture-—-when-your-console-shows-nothing-because-the" aria-label="Permalink to &quot;1. Output capture — when your console shows nothing because the&quot;">​</a></h2><p>text went into a buffer</p><h3 id="the-mechanism" tabindex="-1">The mechanism <a class="header-anchor" href="#the-mechanism" aria-label="Permalink to &quot;The mechanism&quot;">​</a></h3><p>Most service ops are v2.2.0 shell-command bodies that print via <code>screen_console_puts</code>. To serve them through the L1SVC syscall, the dispatcher wraps them in <code>core_kcap_run_fn(fn, arg, out, cap)</code>:</p><ul><li>While a capture is active, the capture hook <strong>IS the console hook</strong> (the console driver holds exactly one hook slot).</li><li>Characters go into the caller&#39;s buffer; both the framebuffer draw and the serial tee are <strong>suppressed</strong> for the duration.</li><li>Captures stack up to 4 levels; the boot serial tee is reinstalled when the last capture ends.</li><li>Overflow is &quot;reported by marking, never by truncating silently&quot;.</li></ul><p>Consequences you will actually meet:</p><ul><li>A command run from a wizard or a script prints <strong>nothing live</strong> — its output went to the capture buffer and is rendered by the caller. This is correct, not a failure.</li><li>If a captured body loops or waits for console input, it looks like a dead machine: the prompt never comes back.</li></ul><h3 id="the-three-routing-styles-why-some-ops-print-live-and-others-do-not" tabindex="-1">The three routing styles (why some ops print live and others do not) <a class="header-anchor" href="#the-three-routing-styles-why-some-ops-print-live-and-others-do-not" aria-label="Permalink to &quot;The three routing styles (why some ops print live and others do not)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Style</th><th>Ops</th><th>Why</th></tr></thead><tbody><tr><td><strong>captured</strong> (<code>core_kcap_run_fn</code>)</td><td>most one-shot text ops (status, listings, tests)</td><td>output belongs to the caller</td></tr><tr><td><strong>direct</strong> (<code>out[0]=0; return fn(arg);</code>)</td><td><code>sshd</code>, all 9 TUI ops, <code>ime -i</code>, <code>power sleep</code></td><td>captured bodies must not sleep — running these captured swallowed live console output (found live during OCIRE-supervised boot)</td></tr><tr><td><strong>buffer-render</strong> (service writes <code>out</code> itself)</td><td>l1, klog, health, diag, fs, time, watchdog dispatchers</td><td>no legacy print body involved</td></tr></tbody></table><p>So when <code>power sleep 2</code> prints its countdown live but <code>health</code> does not echo anything until it returns — that is the routing table, not a bug. And if you ever see <strong>no output at all</strong> from <code>sshd</code> or a TUI page, check the serial console: direct-routed output prefers the live console and can be missed on a slow terminal.</p><h2 id="_2-the-return-value-convention-—-no-errno-to-read" tabindex="-1">2. The return-value convention — no errno to read <a class="header-anchor" href="#_2-the-return-value-convention-—-no-errno-to-read" aria-label="Permalink to &quot;2. The return-value convention — no errno to read&quot;">​</a></h2><p>There is <strong>no global <code>errno</code> variable and no <code>errno.h</code></strong> (freestanding kernel, no libc):</p><ul><li>0 = success, negative = failure (<code>-1</code> generic).</li><li>Precision comes from the 8 dense negative-enum families (61 codes — <a href="./error-codes.html">error-codes.md</a>).</li><li>Ring-buffer APIs return slot indices ≥ 0; <code>-1</code> = past the window.</li><li>Watchdog slot APIs return -1 (table full) / -2 (bad args).</li></ul><p>The trap: a command that fails with <code>-1</code> and prints nothing (the argument was legal but the operation was refused, e.g. writing to the OCIRE-protected recovery disk) leaves <strong>no message anywhere</strong> unless the service chose to klog it. When a command &quot;does nothing&quot;:</p><ol><li>Re-run it and watch <code>dmesg 30</code> in a second step — many refusals are klog WARN/ERROR lines, not console lines.</li><li>Check the family&#39;s <code>_test</code> stub — it exercises the same op with visible verdicts.</li><li>Remember the deliberate refusals: writes to the recovery disk (<code>blk: write ... REFUSED</code> is klog-only), <code>kill</code> of ocire_guard (looks like &quot;no such process&quot;).</li></ol><h2 id="_3-the-honest-skip-pattern-—-a-pass-shaped-non-answer" tabindex="-1">3. The &quot;honest skip&quot; pattern — a PASS-shaped non-answer <a class="header-anchor" href="#_3-the-honest-skip-pattern-—-a-pass-shaped-non-answer" aria-label="Permalink to &quot;3. The &quot;honest skip&quot; pattern — a PASS-shaped non-answer&quot;">​</a></h2><p>Hardware-absent conditions deliberately report <code>(honest skip)</code> / <code>(honest FAIL)</code> instead of failing the suite. Examples:</p><ul><li><code>hpet: legacy route not available (honest skip)</code></li><li><code>oneshot: arm failed (honest FAIL)</code></li><li><code>[audio_rw_test] no sound cards registered =&gt; SKIPPED</code></li><li><code>msitest</code>&#39;s <code>e1000: no MSI cap or BAR0 SKIP (reported honestly)</code></li><li><code>[nic_rw_test] no NICs registered =&gt; SKIP</code></li><li><code>wifi scan</code> in QEMU: the honest &quot;no radio&quot; output</li></ul><p>Reading rule: <strong>a suite that ends in honest skips tested nothing</strong>. If you expected the hardware to be there (you attached the device, you passed the QEMU flag), an honest skip means the probe did not find it — go check the bus (<code>lspci</code>, <code>usb</code>), not the test.</p><h2 id="_4-health-first-—-the-three-alarm-bits" tabindex="-1">4. Health first — the three alarm bits <a class="header-anchor" href="#_4-health-first-—-the-three-alarm-bits" aria-label="Permalink to &quot;4. Health first — the three alarm bits&quot;">​</a></h2><p>The health monitor samples every second and raises exactly three alarms (klog WARN):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alarm: memory &gt;90% used (&lt;used&gt;/&lt;total&gt; KiB)</span></span>
<span class="line"><span>alarm: &lt;n&gt; active tasks (&gt;64)</span></span>
<span class="line"><span>alarm: CPU &gt;=90% busy for 10 consecutive seconds</span></span></code></pre></div><p>Before deep-diving any &quot;slow&quot; or &quot;weird&quot; machine, run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; health              # one snapshot: cpu/mem/heap/tasks/disk/net</span></span>
<span class="line"><span>ush&gt; health watch        # live monitor until ENTER</span></span>
<span class="line"><span>ush&gt; health export       # write the report to a file</span></span></code></pre></div><p>The alarms also feed watchdog slot 0 (&quot;system-heartbeat&quot;) as an extra feed source: an alive-but-alarmed system keeps feeding the dog; a dead one stops, and the WP-11 panic path (dump + crashlog + policy) fires. So a machine that &quot;silently&quot; rebooted was probably alarmed first — <code>health</code> on the next boot plus <code>/var/log/kernel.log</code> tells the story.</p><h2 id="_5-log-level-filtering-—-the-message-you-never-saw" tabindex="-1">5. Log-level filtering — the message you never saw <a class="header-anchor" href="#_5-log-level-filtering-—-the-message-you-never-saw" aria-label="Permalink to &quot;5. Log-level filtering — the message you never saw&quot;">​</a></h2><p>klog has 5 levels (DEBUG 0 … FATAL 4) with per-level emission switches, a live filter, and a global level. If a line never appears:</p><ul><li>The <strong>level is off</strong>: <code>logctl status</code> shows the live level and the per-level mask; <code>logctl level -1</code> is fully muted. Re-enable with <code>logctl enable debug</code> (or the level you need).</li><li>The <strong>filter</strong> ate it: <code>logctl filter</code> settings apply to live channels AND dmesg/logcat replays. <code>logctl filter clear</code> resets.</li><li>The <strong>ring wrapped</strong>: 1024 entries, overwrites counted — the dmesg footer <code>-- &lt;shown&gt; lines (ring &lt;n&gt;/1024, dropped &lt;d&gt;) --</code> shows drops. <code>dmesg 1024</code> for the whole window.</li><li>You looked at the wrong channel: <code>logctl flush</code> writes <code>/var/log/kernel.log</code> (rotate keeps 3: kernel.log.1 ...).</li></ul><p>Quick un-hide:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; logctl level 0           # everything</span></span>
<span class="line"><span>ush&gt; logctl test              # emits one line per level (module klogtest)</span></span>
<span class="line"><span>ush&gt; logcat -l debug -f       # follow everything live; ENTER exits</span></span></code></pre></div><p><code>logctl test</code> is the calibration tool: if its 5 lines appear, the pipeline works and your target message genuinely was not emitted.</p><h2 id="_6-crashlog-—-the-32-slot-history-you-forgot-existed" tabindex="-1">6. Crashlog — the 32-slot history you forgot existed <a class="header-anchor" href="#_6-crashlog-—-the-32-slot-history-you-forgot-existed" aria-label="Permalink to &quot;6. Crashlog — the 32-slot history you forgot existed&quot;">​</a></h2><p><code>crashlog</code> records every panic into a 32-entry ring (fields include vector, rip, rsp, cr2, tid/pid, task name), flushed to <code>/var/log/crash.log</code>; core dumps go to <code>/var/crash/core.dump</code>. After any unexplained reset:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; crashlog          # were there panics you never saw?</span></span>
<span class="line"><span>ush&gt; dumpinfo          # core dump buffer status</span></span>
<span class="line"><span>ush&gt; dmesg 100         # this boot&#39;s klog</span></span>
<span class="line"><span>ush&gt; cat /var/log/crash.log</span></span></code></pre></div><p>Empty output prints <code>no dump captured yet (trigger: crashtest panic|exc|pf)</code> — which is also how you verify the machinery on a healthy machine. A #DF panic is deliberately minimal (one static serial line, no record/dump/flush — stated in KNOWN_ISSUES): if the machine died with a one-line banner, check <strong>serial</strong>, not crashlog.</p><h2 id="_7-ota-that-silently-does-not-update-—-the-six-cause-chain" tabindex="-1">7. OTA that silently does not update — the six-cause chain <a class="header-anchor" href="#_7-ota-that-silently-does-not-update-—-the-six-cause-chain" aria-label="Permalink to &quot;7. OTA that silently does not update — the six-cause chain&quot;">​</a></h2><p><code>update</code>/<code>checkupdate</code> failing quietly is the classic silent failure because most of the chain fails inside codes, not console text. Walk the six causes in order:</p><table tabindex="0"><thead><tr><th>#</th><th>Cause</th><th>How to see it</th><th>Fix</th></tr></thead><tbody><tr><td>1</td><td><code>update_url</code> wrong (bad scheme/typo)</td><td><code>config get update_url</code></td><td><code>config set update_url http://host/path</code> (must be http:// or https://)</td></tr><tr><td>2</td><td>DNS cannot resolve the update host</td><td><code>dns &lt;host&gt;</code> → <code>DNS resolution failed</code></td><td>fix DNS server (re-run <code>dhcp</code>, or set <code>ip &lt;a&gt; &lt;m&gt; &lt;g&gt;</code> and check the DNS field)</td></tr><tr><td>3</td><td>No A/B disk</td><td><code>update status</code> lacks <code>A/B disk: present</code></td><td><code>lsblk</code> → <code>abdisk &lt;dev&gt;</code> (destructive; wizard-guarded)</td></tr><tr><td>4</td><td>Signature/verification failed</td><td>re-run <code>update</code> — the <code>&lt;why&gt;</code> is <code>SHA256 mismatch</code> / <code>package (tar.gz) invalid</code></td><td>re-download; verify the server&#39;s package_sha256</td></tr><tr><td>5</td><td>Version comparison says up-to-date</td><td><code>checkupdate</code> prints <code>Current version is up to date.</code></td><td>not a failure — the feed&#39;s version field must exceed yours; check the server&#39;s update.json</td></tr><tr><td>6</td><td>Network fully down</td><td><code>ip</code> shows 0.0.0.0; <code>ping &lt;gw&gt;</code> fails</td><td><code>dhcp</code> (or static <code>ip</code>), then re-check</td></tr></tbody></table><p>Two extra quiet paths: <code>online_update=no</code> in the config makes the <strong>autoupdate</strong> background path skip silently (<code>[autoupdate] skipped: network not ready</code> is klog-only) — <code>config get online_update</code>; and <code>auto_check=no</code> similarly disables the boot-time check.</p><p>The 5-step <code>update</code> wizard (no arguments) walks causes 1→3→6 in order (IP probe → DHCP offer → A/B disk probe → DNS → check → install), so when in doubt just run <code>update</code> with no arguments and read the <code>[n/5]</code> step that fails.</p><h2 id="_8-serial-echo-and-the-eaten-e-—-tolerant-reading" tabindex="-1">8. Serial echo and the eaten <code>&quot;e&quot;</code> — tolerant reading <a class="header-anchor" href="#_8-serial-echo-and-the-eaten-e-—-tolerant-reading" aria-label="Permalink to &quot;8. Serial echo and the eaten \`&quot;e&quot;\` — tolerant reading&quot;">​</a></h2><p>The serial console is both an input and an output channel; when the guest echoes your keystroke while printing, the echo can overlap in-flight output. The classic artifact: a bracketed tag like <code>[ocse]</code> arrives as <code>[ega]</code> wait — exactly: the serial-echo overlap <strong>eats the leading <code>e</code> of <code>ega]</code>-shaped fragments</strong> (the tooling calls it the <code>ega]</code> phenomenon). What you see on screen can be a character-shifted version of what the guest printed.</p><p>Tolerant reading rules (the same ones the E2E tooling uses):</p><ul><li>Treat <code>[tag]</code> brackets as <strong>optional</strong> when grepping boot output — match on the inner words, not the punctuation.</li><li>Strip the echoed command line before matching (the guest echoes what you typed, then prints the result).</li><li>Expect ANSI CSI sequences interleaved; strip them before regex.</li><li>Keystrokes a serial link cannot carry (arrows, Home/End) must go in via the QEMU monitor <code>sendkey</code>, not by typing escape codes — CSI bytes over a TCP socket arrive too late at boot-menu time.</li><li>Known flake: QEMU intermittently drops serial RX bytes right after an HMP screendump (verified with an in-kernel RX trace) — never take screenshots in the middle of a functional round; re-run flapping checks isolated.</li></ul><p>If a single weird character is your only symptom, re-run the command before debugging the OS: it is usually the link, not the kernel.</p><h2 id="_9-a-checklist-for-nothing-happened" tabindex="-1">9. A checklist for &quot;nothing happened&quot; <a class="header-anchor" href="#_9-a-checklist-for-nothing-happened" aria-label="Permalink to &quot;9. A checklist for &quot;nothing happened&quot;&quot;">​</a></h2><ol><li><code>health</code> — alarms? (memory/tasks/CPU)</li><li><code>dmesg 100</code> — any WARN/ERROR from the family? (mind the level filter: <code>logctl status</code>)</li><li><code>crashlog</code> + <code>dumpinfo</code> — did something die earlier?</li><li>Re-run the command and watch for the <strong>return path</strong>: silent <code>-1</code> usually means a deliberate refusal (protected disk, guard channel, disabled feature — see §2).</li><li>Was the output <strong>captured</strong> (§1)? Run the op from the bare command instead of the wizard, or vice versa.</li><li>OTA-shaped problem → the six-cause chain (§7).</li><li>Garbled single characters → serial echo (§8); re-run first.</li><li>Still nothing: capture serial (<code>-serial file:boot.log</code>) and check the klog ring for FATAL lines that never reached the screen — the serial console is authoritative.</li></ol><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./error-codes.html">error-codes.md</a> — the codes behind quiet refusals</li><li><a href="./error-catalog.html">error-catalog.md</a> — the loud failures, by subsystem</li><li><a href="./../manual/hidden-commands.html">../manual/hidden-commands.md</a> — the stubs that make kernel paths print verdicts</li><li><a href="./qemu-debugging.html">qemu-debugging.md</a> — capture techniques</li></ul>`,53)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
